// "I would like to be 300 wide" — a preference, not a demand
let w = box.widthAnchor.constraint(equalToConstant: 300)
w.priority = .defaultHigh      // 750

NSLayoutConstraint.activate([
    w,
    // "never wider than the parent minus 40" — required, 1000
    box.widthAnchor.constraint(lessThanOrEqualTo: superview.widthAnchor, constant: -40)
])
// On a 320-point parent: 280 wins, because the required one cannot be given up.

// Changing it later: start below required, not at it
let h = box.heightAnchor.constraint(equalToConstant: 80)
h.priority = .init(999)        // so it can be lowered afterwards

