final class BigTapButton: UIButton {
    override func point(inside point: CGPoint, with event: UIEvent?) -> Bool {
        bounds.insetBy(dx: -12, dy: -12).contains(point)
    }
}

// The classic trap: visible outside the parent, but not tappable there
parent.clipsToBounds = false   // you can see it
// the parent still fails point(inside:), so the search never reaches the button

// Dismiss the keyboard without knowing which field has it
UIApplication.shared.sendAction(
    #selector(UIResponder.resignFirstResponder),
    to: nil, from: nil, for: nil)

// Same thing, shorter, when you have the container view
view.endEditing(true)

// A target of nil: the action travels up until somebody implements it
button.addTarget(nil, action: #selector(copy(_:)), for: .touchUpInside)

// Receiving in the controller something no view handled
override func motionEnded(_ motion: UIEvent.EventSubtype, with event: UIEvent?) {
    if motion == .motionShake { undo() }
}

// An image view needs this, or nothing happens at all
imageView.isUserInteractionEnabled = true

let singleTap = UITapGestureRecognizer(target: self, action: #selector(tapped))
let doubleTap = UITapGestureRecognizer(target: self, action: #selector(doubleTapped))
doubleTap.numberOfTapsRequired = 2

// The single tap waits to see whether a double is coming
singleTap.require(toFail: doubleTap)

imageView.addGestureRecognizer(singleTap)
imageView.addGestureRecognizer(doubleTap)

// Dismiss the keyboard without eating the table's taps
let dismissTap = UITapGestureRecognizer(target: self, action: #selector(hideKeyboard))
dismissTap.cancelsTouchesInView = false     // let it through as well
view.addGestureRecognizer(dismissTap)

// Old form: @objc is needed because a selector is an Objective-C name
button.addTarget(self, action: #selector(saveTapped), for: .touchUpInside)

@objc private func saveTapped() { save() }

// New form: a closure, and no selector in sight
button.addAction(UIAction { [weak self] _ in
    self?.save()                       // [weak self]: the closure holds what it captures
}, for: .touchUpInside)

// The right event for each control
toggle.addAction(UIAction { _ in }, for: .valueChanged)
field.addAction(UIAction { _ in }, for: .editingChanged)

// A quick check, in the debugger
print(view.isUserInteractionEnabled)
print(view.superview?.isUserInteractionEnabled ?? true)   // and all the way up
print(view.alpha, view.isHidden)

// Who is really under this point?
let hit = window.hitTest(point, with: nil)
print(type(of: hit!))        // often not the view you expected

